//! 🖼️ Four pixel intents prepare one semantic leaf through original geometry and output custody.
use crate::{RasterCommand,config::{RasterConfig,RasterConfigMutation},commands::{apply_filter,fill_region,fill_selection,transform_image,paint_stroke::hex_color}};
use crate::commands::work_app::RasterWorkApp;
use semio_s_artifact_raster_raster_model::{snapshot::RasterSnapshot,RASTER_OWNED_FIELD_BYTES};
use semio_s_artifact_raster_raster_mutations::RasterMutation;
use semio_s_artifact_raster_raster_mutations_pixels::{fill_region as fill_leaf,fill_selection as selection_leaf,apply_filter as filter_leaf,transform_image as transform_leaf};
use semio_s_artifact_raster_raster_host::RasterPixelSourceWork;
use semio_plugin::{Emit,retained_command::{ArtifactCommandInputs,ArtifactCommandWork,ArtifactCommandWorkStep}};
use semio_framework_job::{StepContext,OriginalTurnFailure,OriginalSourceBinding,InteractiveJobCloseStep,receive_original_retained_work};
use semio_framework_value::{RetirementDemand,ValueError,ValueRefusalKind,RetainedCloneGrant,RetainedCloneProgress,RetainedCloneStep,RetainedWorkOutcome,retained_clone::retained_clone_grant_admits};
use std::mem::{size_of,ManuallyDrop};

#[derive(Clone,Copy,PartialEq,Eq)]
enum Route{Fill,Filter,Transform,Selection}
impl Route{fn id(self)->&'static str{match self{Self::Fill=>"fillRegion",Self::Filter=>"applyFilter",Self::Transform=>"transformImage",Self::Selection=>"fillSelection"}}}
#[derive(semio_framework_value::RetireOwned)]
enum Request{Fill(fill_region::FillRegion),Filter(apply_filter::ApplyFilter),Transform(transform_image::TransformImage),Selection(fill_selection::FillSelection)}
impl Request{fn layer(&self)->&str{match self{Self::Fill(value)=>&value.layer_id,Self::Filter(value)=>&value.layer_id,Self::Transform(value)=>&value.layer_id,Self::Selection(value)=>&value.layer_id}}}
#[derive(semio_framework_value::RetireOwned)]
struct Owned{request:Option<Request>,leaf:Option<RasterMutation>,actor:Option<protocol::ActorId>,tool:Option<String>,clock:Option<protocol::HybridLogicalTimestamp>,transaction:Option<protocol::TransactionRef>,rows:Vec<RasterMutation>}
pub struct PixelLeafWork{route:Route,owned:ManuallyDrop<Option<Owned>>,source:Option<RasterPixelSourceWork>,retirement:ManuallyDrop<Option<Box<dyn store::ErasedSnapshotRetirement>>>,original:Option<OriginalSourceBinding>,inputs:Option<(usize,usize,usize,usize)>,stage:u8,closing:bool}
fn invalid(message:&'static str)->ValueError{ValueError::literal(ValueRefusalKind::InvalidValue,message)}
fn quote(copy:usize,capacity:usize)->RetirementDemand{RetirementDemand{copy_bytes:copy,capacity_bytes:capacity,depth:1,..Default::default()}}
fn fixed(copy:usize)->RetainedCloneProgress{RetainedCloneProgress{copied_items:1,copied_bytes:copy,..Default::default()}}
fn posted(cx:&mut StepContext<'_>,progress:RetainedCloneProgress)->Result<(),OriginalTurnFailure>{receive_original_retained_work(cx,RetainedWorkOutcome{result:Ok(RetainedCloneStep::Progress(progress)),work:0})?;Ok(())}
fn exact(value:&str)->String{let bytes=Box::<[u8]>::new_uninit_slice(value.len());let mut bytes=bytes;for(index,byte)in value.bytes().enumerate(){bytes[index].write(byte);}let bytes=unsafe{bytes.assume_init()}.into_vec();unsafe{String::from_utf8_unchecked(bytes)}}
fn one_row()->Vec<RasterMutation>{let storage=Box::new(std::mem::MaybeUninit::<RasterMutation>::uninit());unsafe{Vec::from_raw_parts(Box::into_raw(storage).cast::<RasterMutation>(),0,1)}}

impl PixelLeafWork{
 pub fn new(tool:&str)->Self{let route=match tool{"fillRegion"=>Route::Fill,"applyFilter"=>Route::Filter,"transformImage"=>Route::Transform,"fillSelection"=>Route::Selection,_=>panic!("closed Raster pixel producer route")};Self{route,owned:ManuallyDrop::new(Some(Owned{request:None,leaf:None,actor:None,tool:None,clock:None,transaction:None,rows:Vec::new()})),source:None,retirement:ManuallyDrop::new(None),original:None,inputs:None,stage:0,closing:false}}
 fn data(&self)->Result<&Owned,ValueError>{self.owned.as_ref().ok_or_else(||invalid("Raster pixel producer owner is absent"))}
 fn request(&self)->Result<&Request,ValueError>{self.data()?.request.as_ref().ok_or_else(||invalid("Raster pixel command owner is absent"))}
 fn validate_original(&self,cx:&StepContext<'_>)->Result<(),ValueError>{if self.original.is_some_and(|source|!source.matches(cx)){return Err(invalid("Raster pixel producer changed its original caller"))}Ok(())}
 pub fn receive(&mut self,command:&mut RasterCommand,cx:&mut StepContext<'_>)->Result<bool,OriginalTurnFailure>{
  self.validate_original(cx)?;if self.data()?.request.is_some(){return Ok(true)}if self.closing||command.command_id()!=self.route.id(){return Err(invalid("Raster pixel command differs from its exact producer").into())}let d=quote(2*size_of::<Request>()+size_of::<Option<OriginalSourceBinding>>(),0);if cx.should_yield()||!cx.retained_work_can_enter(d){return Ok(false)}let request=match command{RasterCommand::FillRegion(value)=>Request::Fill(fill_region::FillRegion{layer_id:std::mem::take(&mut value.layer_id),x:value.x,y:value.y}),RasterCommand::ApplyFilter(value)=>Request::Filter(apply_filter::ApplyFilter{layer_id:std::mem::take(&mut value.layer_id),filter:std::mem::take(&mut value.filter),amount:value.amount}),RasterCommand::TransformImage(value)=>Request::Transform(transform_image::TransformImage{layer_id:std::mem::take(&mut value.layer_id),operation:std::mem::take(&mut value.operation),x:value.x,y:value.y,width:value.width,height:value.height,bilinear:value.bilinear}),RasterCommand::FillSelection(value)=>Request::Selection(fill_selection::FillSelection{layer_id:std::mem::take(&mut value.layer_id)}),_=>return Err(invalid("Raster pixel command is outside its closed producer").into())};self.original=Some(OriginalSourceBinding::borrow(cx));self.owned.as_mut().unwrap().request=Some(request);cx.consume_fuel(1);posted(cx,fixed(d.copy_bytes))?;Ok(true)
 }
 fn clipped(&self)->bool{match self.request(){Ok(Request::Transform(_))=>false,Ok(Request::Filter(value))=>!matches!(value.filter.as_str(),"flipHorizontal"|"flipVertical"),_=>true}}
 fn target<'a>(&self,config:&'a RasterConfig)->&'a str{config.paint_target.as_str()}
 fn demands(&self,snapshot:&RasterSnapshot,config:&RasterConfig,seed:&str,body:usize)->Result<RetirementDemand,ValueError>{
  Ok(match self.stage{0=>quote(size_of::<(usize,usize,usize,usize,u8)>(),0),1=>RasterPixelSourceWork::begin_demands(snapshot,self.request()?.layer(),self.target(config))?,2=>self.source.as_ref().ok_or_else(||invalid("Raster pixel geometry source is absent"))?.geometry_demands(body)?,3=>{let bytes=if matches!(self.route,Route::Fill|Route::Selection){config.paint_target.len()+4*size_of::<f64>()}else{0};quote(2*size_of::<RasterMutation>()+size_of::<Request>()+bytes,bytes)},4=>protocol::ActorId::seed_demands(seed)?,5=>quote(size_of::<protocol::HybridLogicalTimestamp>()+size_of::<String>()+fill_region::RASTER_FILL_TOOL_ID.len(),fill_region::RASTER_FILL_TOOL_ID.len()),6=>protocol::TransactionRef::original_mint_demands(self.data()?.actor.as_ref().ok_or_else(||invalid("Raster fill actor is absent"))?,self.data()?.clock.as_ref().ok_or_else(||invalid("Raster fill clock is absent"))?,self.data()?.tool.as_deref().ok_or_else(||invalid("Raster fill tool is absent"))?)?,7=>quote(size_of::<Vec<RasterMutation>>(),size_of::<RasterMutation>()),8=>quote(2*size_of::<RasterMutation>()+size_of::<Emit<RasterMutation,RasterConfigMutation>>()+size_of::<Option<protocol::TransactionRef>>(),0),_=>quote(0,0)})
 }
 fn build(&mut self,config:&RasterConfig)->Result<RetainedCloneProgress,ValueError>{
  let selected=if self.clipped(){config.pixel_selection.as_ref().filter(|selection|selection.layer_id==self.request().unwrap().layer()&&selection.target==config.paint_target)}else{None};if let Some(selection)=selected{selection.validate_fields().map_err(invalid)?;}let target=config.paint_target.as_str();let color=if matches!(self.route,Route::Fill|Route::Selection){Some(if target=="mask"{let grey=f64::from(config.mask_value.min(255))/255.0;vec![grey,grey,grey,if self.route==Route::Selection&&config.brush_opacity.is_finite(){config.brush_opacity.clamp(0.0,1.0)}else{1.0}]}else{hex_color(&config.brush_color).ok_or_else(||invalid("raster.brush.color-invalid"))?})}else{None};let clip=selected.map(|selection|selection.spans.clone());let cap=color.as_ref().map_or(0,|value|value.capacity()*size_of::<f64>())+if color.is_some(){target.len()}else{0};let data=self.owned.as_mut().unwrap();let leaf=match data.request.as_mut().unwrap(){Request::Fill(value)=>RasterMutation::FillRegion(fill_leaf::FillRegion{layer_id:std::mem::take(&mut value.layer_id),target:exact(target),seed:fill_leaf::RasterSeed{x:value.x.floor()as u32,y:value.y.floor()as u32},tolerance:config.fill_tolerance,color:color.unwrap(),selection:clip}),Request::Filter(value)=>RasterMutation::ApplyFilter(filter_leaf::ApplyFilter{layer_id:std::mem::take(&mut value.layer_id),filter:std::mem::take(&mut value.filter),amount:value.amount,selection:clip}),Request::Transform(value)=>RasterMutation::TransformImage(transform_leaf::TransformImage{layer_id:std::mem::take(&mut value.layer_id),operation:std::mem::take(&mut value.operation),x:value.x,y:value.y,width:value.width,height:value.height,bilinear:value.bilinear}),Request::Selection(value)=>RasterMutation::FillSelection(selection_leaf::FillSelection{layer_id:std::mem::take(&mut value.layer_id),target:exact(target),color:color.unwrap(),selection:clip})};data.leaf=Some(leaf);Ok(RetainedCloneProgress{retained_capacity_bytes:cap,..fixed(2*size_of::<RasterMutation>()+size_of::<Request>()+cap)})
 }
 pub fn advance(&mut self,snapshot:&RasterSnapshot,config:&RasterConfig,seed:&str,cx:&mut StepContext<'_>)->Result<Option<Emit<RasterMutation,RasterConfigMutation>>,OriginalTurnFailure>{
  self.validate_original(cx)?;if self.closing||self.stage>8{return Err(invalid("Raster pixel producer is closed").into())}if cx.should_yield(){return Ok(None)}let inputs=(snapshot as*const RasterSnapshot as usize,config as*const RasterConfig as usize,seed.as_ptr()as usize,seed.len());if self.inputs.is_some_and(|original|original!=inputs){return Err(invalid("Raster pixel producer sources changed").into())}let d=self.demands(snapshot,config,seed,cx.retained_grant().maximum_copy_bytes)?;if !cx.retained_work_can_enter(d){return Ok(None)}let grant=cx.retained_grant();let fixed_work=self.stage!=4;let result=(||{
  match self.stage{
   0=>{let request=self.request()?;if request.layer().len()>RASTER_OWNED_FIELD_BYTES||seed.len()>RASTER_OWNED_FIELD_BYTES||config.paint_target.len()>16{return Err(invalid("Raster pixel command metadata is invalid").into())}if config.paint_target!="pixels"{match self.route{Route::Filter=>return Err(invalid("raster.filter.pixels-only").into()),Route::Transform=>return Err(invalid("raster.transform.pixels-only").into()),_=>{}}}match request{Request::Fill(value)if !value.x.is_finite()||!value.y.is_finite()||value.x<0.0||value.y<0.0||config.fill_tolerance>255=>return Err(invalid("raster.fill.seed-invalid").into()),Request::Filter(value)if value.filter.len()>64=>return Err(invalid("raster.filter.invalid").into()),Request::Transform(value)if value.operation.len()>64=>return Err(invalid("raster.transform.invalid").into()),_=>{}}self.inputs=Some(inputs);self.stage=1;posted(cx,fixed(d.copy_bytes))?;},
   1=>{if let Some((source,p))=RasterPixelSourceWork::begin(snapshot,self.request()?.layer(),self.target(config),grant)?{self.source=Some(source);self.stage=2;posted(cx,p)?;}},
   2=>{let(step,descriptor)={let source=self.source.as_mut().unwrap();let step=source.advance_geometry(snapshot,grant)?;let descriptor=if matches!(step,RetainedCloneStep::Complete(_)){let descriptor=source.descriptor()?;Some((descriptor.protected,descriptor.visible,descriptor.width,descriptor.height))}else{None};(step,descriptor)};posted(cx,step.progress())?;if let Some((protected,visible,width,height))=descriptor{if protected{return Err(invalid("raster-layer-locked").into())}if !visible{return Err(invalid("raster.paint.layer-hidden").into())}if self.clipped(){if let Some(selection)=config.pixel_selection.as_ref().filter(|selection|selection.layer_id==self.request().unwrap().layer()&&selection.target==config.paint_target){if(selection.width,selection.height)!=(width,height){return Err(invalid("Raster pixel selection extent changed").into())}}}self.stage=3;}},
   3=>{let p=self.build(config)?;posted(cx,p)?;let leaf=self.data()?.leaf.as_ref().unwrap();let valid=match leaf{RasterMutation::ApplyFilter(value)=>filter_leaf::invalid_field(value).is_none(),RasterMutation::TransformImage(value)=>transform_leaf::invalid_field(value).is_none(),_=>true};if !valid{return Err(invalid(if self.route==Route::Filter{"raster.filter.invalid"}else{"raster.transform.invalid"}).into())}self.stage=if self.route==Route::Fill&&!seed.is_empty(){4}else{7};},
   4=>{let turn=protocol::ActorId::admit_seed(seed,grant);let result=turn.result.map(|value|{if let Some((actor,p))=value{self.owned.as_mut().unwrap().actor=Some(actor);self.stage=5;RetainedCloneStep::Progress(p)}else{RetainedCloneStep::Progress(Default::default())}});receive_original_retained_work(cx,RetainedWorkOutcome{result,work:turn.work})?;},
   5=>{let now=cx.now_us().ok_or_else(||invalid("original fill clock is unavailable"))?;let data=self.owned.as_mut().unwrap();data.clock=Some(protocol::HybridLogicalTimestamp{actor:0,physical_ms:now/1000,logical:0});data.tool=Some(exact(fill_region::RASTER_FILL_TOOL_ID));self.stage=6;posted(cx,RetainedCloneProgress{retained_capacity_bytes:data.tool.as_ref().unwrap().capacity(),..fixed(d.copy_bytes)})?;},
   6=>{let data=self.owned.as_mut().unwrap();let tool=data.tool.take().unwrap();match protocol::TransactionRef::mint_original(data.actor.as_ref().unwrap(),data.clock.as_ref().unwrap(),tool,grant){Ok((transaction,p))=>{data.transaction=Some(transaction);self.stage=7;posted(cx,p)?;},Err((error,tool))=>{data.tool=Some(tool);receive_original_retained_work(cx,RetainedWorkOutcome::<RetainedCloneStep>{result:Err(error),work:0})?;}}},
   7=>{self.owned.as_mut().unwrap().rows=one_row();self.stage=8;posted(cx,RetainedCloneProgress{retained_capacity_bytes:size_of::<RasterMutation>(),..fixed(d.copy_bytes)})?;},
   8=>{let data=self.owned.as_mut().unwrap();data.rows.push(data.leaf.take().unwrap());let emit=Emit{artifact_mutations:std::mem::take(&mut data.rows),transaction:data.transaction.take(),..Default::default()};self.stage=9;posted(cx,fixed(d.copy_bytes))?;return Ok(Some(emit));},_=>unreachable!(),
  }Ok(None)
  })();if fixed_work{cx.consume_fuel(1);}result
 }
 pub fn begin_close(&mut self){self.closing=true}
 pub fn close_demands(&self,body:usize)->Result<RetirementDemand,ValueError>{if let Some(source)=self.source.as_ref(){return if source.terminal_is_empty(){Ok(quote(size_of::<Option<RasterPixelSourceWork>>(),0))}else{source.close_demands(body)}}if let Some(active)=self.retirement.as_ref(){return store::os_store::snapshot_read::artifact_retirement_box_demands(active,body)}if self.owned.is_some(){return store::os_store::snapshot_read::artifact_retirement_owned_birth_demands(&self.owned)}Ok(Default::default())}
 pub fn close_one(&mut self,grant:RetainedCloneGrant)->RetainedWorkOutcome{self.closing=true;if let Some(source)=self.source.as_mut(){if !source.terminal_is_empty(){return source.close_step(grant)}let d=quote(size_of::<Option<RasterPixelSourceWork>>(),0);if !retained_clone_grant_admits(grant,d){return RetainedWorkOutcome{result:Ok(RetainedCloneStep::Progress(Default::default())),work:0}}self.source.take();return RetainedWorkOutcome{result:Ok(RetainedCloneStep::Progress(fixed(d.copy_bytes))),work:1}}if self.retirement.is_some(){store::os_store::snapshot_read::artifact_retirement_box_close_step(&mut self.retirement,grant)}else{store::os_store::snapshot_read::artifact_retirement_admit_owned(&mut self.owned,&mut self.retirement,grant)}}
 pub fn terminal_is_empty(&self)->bool{self.closing&&self.source.is_none()&&self.owned.is_none()&&self.retirement.is_none()}
}
impl<A:RasterWorkApp> ArtifactCommandWork<A> for PixelLeafWork{
 fn tool_id(&self)->&'static str{self.route.id()}
 fn receive_original_command(&mut self,command:&mut RasterCommand,cx:&mut StepContext<'_>)->Result<bool,OriginalTurnFailure>{self.receive(command,cx)}
 fn extent(&self,command:&RasterCommand,_:&RasterSnapshot,_:&protocol::InteractionState,_:Option<&semio_plugin::app::ArtifactOwnedToolJobContext<A>>)->Option<usize>{(command.command_id()==self.route.id()).then_some(1)}
 fn work_demands(&self,input:&ArtifactCommandInputs<'_,A>,body:usize)->Result<RetirementDemand,ValueError>{self.demands(input.snapshot,input.config,input.operation.authoring_seed.as_str(),body)}
 fn step(&mut self,input:&ArtifactCommandInputs<'_,A>,cx:&mut StepContext<'_>)->Result<ArtifactCommandWorkStep<A>,OriginalTurnFailure>{Ok(match self.advance(input.snapshot,input.config,input.operation.authoring_seed.as_str(),cx)?{Some(emit)=>ArtifactCommandWorkStep::Complete(emit),None=>ArtifactCommandWorkStep::Progress{stage:if self.stage<=2{"pixel-target"}else{"pixel-intent"},preview:b""}})}
 fn begin_close(&mut self){PixelLeafWork::begin_close(self)}
 fn close_step(&mut self,cx:&mut StepContext<'_>)->Result<InteractiveJobCloseStep,OriginalTurnFailure>{self.validate_original(cx)?;let turn=self.close_one(cx.retained_grant());cx.consume_fuel(turn.work);let step=turn.result?;Ok(if self.terminal_is_empty(){InteractiveJobCloseStep::Complete{progress:step.progress()}}else{InteractiveJobCloseStep::Pending{progress:step.progress()}})}
 fn next_close_copy_byte_demand(&self)->Result<usize,ValueError>{Ok(self.close_demands(32768)?.copy_bytes)}
 fn next_close_capacity_byte_demand(&self,body:usize)->Result<usize,ValueError>{Ok(self.close_demands(body)?.capacity_bytes)}
 fn next_close_release_byte_demand(&self)->Result<usize,ValueError>{Ok(self.close_demands(32768)?.release_bytes)}
 fn next_close_depth_demand(&self)->Result<usize,ValueError>{Ok(self.close_demands(32768)?.depth)}
 fn terminal_is_empty(&self)->bool{PixelLeafWork::terminal_is_empty(self)}
}
impl Drop for PixelLeafWork{fn drop(&mut self){assert!(std::thread::panicking()||self.terminal_is_empty(),"Raster pixel producer requires original close");}}
